                // When either lag is 0, segments are copied immediately without any delay.
                boolean copyImmediately = copyLagMs == 0 || copyLagBytes == 0;
                // When neither lag is 0 and both are non-positive (e.g. both local retentions are unlimited/-1),
                // there is no bound to trigger a copy, so no segments are eligible.
                boolean noSegmentsEligible = !copyImmediately && copyLagMs <= 0 && copyLagBytes <= 0;

